sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ritm = steps('100').request_item;
  var me = gs.getUserID();                                   // the impersonated requester
  var appr = new GlideRecord('sysapproval_approver');
  appr.addQuery('sysapproval', ritm);
  appr.query();
  var assignedToRequester = false, stillPending = false;
  while (appr.next()) {
    if (appr.approver == me) assignedToRequester = true;      // requester should NOT be an approver
    if (appr.state == 'requested') stillPending = true;
  }
  if (assignedToRequester) { stepResult.setFailed('SoD violated: an approval is assigned to the requester'); return; }
  stillPending
    ? stepResult.setSuccess()                                 // still awaiting a real approver
    : stepResult.setFailed('expected the approval to remain pending for a separate approver');
})(outputs, steps, stepResult);

table = sc_req_item
conditions = sys_id={RITM from step 1}
assert = state != 3 (Closed Complete)
